import {openEventPurge} from './event-purge.js';
export function confirmDeleteEvent(event,client,onDeleted,isCurrent=()=>true){
 const modal=document.querySelector('#modal'),body=document.querySelector('#modalBody');body.replaceChildren();delete modal.dataset.applicationId;
 const heading=document.createElement('h2');heading.textContent='ลบกิจกรรม';const name=document.createElement('p');name.textContent=event.name;name.style.fontWeight='700';name.style.overflowWrap='anywhere';const impact=document.createElement('p');impact.textContent='กิจกรรมจะหายจากหน้าเว็บ และปิดรับสมัครกับเช็คอินทันที ใบสมัคร บัตร และประวัติเช็คอินจะยังเก็บไว้ คุณกู้คืนได้จากถังขยะกิจกรรม';const seats=document.createElement('p');seats.className='sub';seats.textContent='ที่นั่งที่ใช้หรือกันไว้ขณะนี้ '+(event.reservedCount||0)+' คน · ข้อมูลนี้จะไม่ถูกล้าง';
 const form=document.createElement('form');form.innerHTML='<label>พิมพ์คำว่า “ลบ” เพื่อยืนยัน<input name="confirmation" required autocomplete="off" placeholder="ลบ"></label><div class="event-delete-buttons"><button class="danger-outline" type="submit" disabled>ย้ายไปถังขยะ</button><button type="button">ยกเลิก</button></div><p role="status" aria-live="polite"></p>';
 const confirm=form.querySelector('button[type=submit]'),cancel=form.querySelector('button[type=button]'),status=form.querySelector('[role=status]');let busy=false;
 form.elements.confirmation.oninput=()=>confirm.disabled=busy||form.elements.confirmation.value.trim()!=='ลบ';cancel.onclick=()=>modal.close();
 form.onsubmit=async e=>{e.preventDefault();if(busy||!isCurrent()||form.elements.confirmation.value.trim()!=='ลบ')return;busy=true;confirm.disabled=true;cancel.disabled=true;status.textContent='กำลังย้ายกิจกรรมไปถังขยะ…';try{await client.operate({action:'deleteEvent',eventId:event.id,expectedName:event.name,confirmation:'DELETE'});if(body.contains(form))modal.close();if(isCurrent())onDeleted?.()}catch(error){if(body.contains(form))status.textContent=error.message||'ลบไม่ได้ กรุณาลองใหม่'}finally{busy=false;confirm.disabled=form.elements.confirmation.value.trim()!=='ลบ';cancel.disabled=false}};
 body.append(heading,name,impact,seats,form);modal.showModal();form.elements.confirmation.focus();
}
export function mountEventTrash(root,client,isCurrent=()=>true){
 root.innerHTML='<h3>ถังขยะกิจกรรม</h3><p class="sub">เลือกกู้คืนเพื่อเก็บประวัติและใช้งานต่อ หรือเลือกลบถาวรเพื่อลบข้อมูลกิจกรรมและไฟล์ที่เกี่ยวข้องออกจาก Firebase</p><p role="status">กำลังโหลด…</p><div class="admin-event-list"></div>';const status=root.querySelector('[role=status]'),list=root.querySelector('.admin-event-list');let disposed=false;
 const active=()=>!disposed&&isCurrent();
 const stop=client.watchAdminEvents(events=>{if(!active())return;list.replaceChildren();const deleted=events.filter(event=>event.deleted===true).sort((a,b)=>(b.deletedAt?.toMillis?.()||0)-(a.deletedAt?.toMillis?.()||0));status.textContent=deleted.length?'กิจกรรมในถังขยะ '+deleted.length+' รายการ':'ยังไม่มีกิจกรรมในถังขยะ';
  for(const event of deleted){const row=document.createElement('article');row.className='admin-event-row';const info=document.createElement('div'),heading=document.createElement('h3'),date=document.createElement('p');heading.textContent=event.name;date.className='sub';date.textContent=(event.date||'')+(event.purging?' · กำลังลบถาวร ข้อมูลบางส่วนอาจถูกลบแล้ว':' · ข้อมูลผู้สมัครและประวัติยังอยู่');info.append(heading,date);const restore=document.createElement('button');restore.className='primary';restore.textContent=event.purging?'กู้คืนไม่ได้ระหว่างลบถาวร':'กู้คืนกิจกรรม';restore.disabled=event.purging===true;restore.onclick=async()=>{if(!active()||!confirm('กู้คืนกิจกรรม “'+event.name+'”? ระบบจะยังปิดรับสมัครและเช็คอินไว้'))return;restore.disabled=true;try{await client.operate({action:'restoreEvent',eventId:event.id});if(active())status.textContent='กู้คืนแล้ว ไปจัดการกิจกรรมเพื่อเปิดรับสมัครหรือเช็คอิน'}catch(error){if(active()){status.textContent=error.message||'กู้คืนไม่ได้';restore.disabled=false}}};const thumb=document.createElement('div');thumb.className='admin-event-thumb';thumb.textContent='KUSK';const actions=document.createElement('div');actions.className='admin-event-actions';const purge=document.createElement('button');purge.className='danger-outline';purge.textContent=event.purging?'ดำเนินการลบต่อ':'ลบถาวร';purge.onclick=()=>{if(active())openEventPurge(event,client,active)};actions.append(restore,purge);row.append(thumb,info,actions);list.append(row)}
 },()=>{if(active()){list.replaceChildren();status.textContent='โหลดถังขยะไม่ได้ กรุณาตรวจสิทธิ์หรือเข้าสู่ระบบใหม่'}});
 return ()=>{disposed=true;stop()};
}
